/* Stacked Regression Tables: Summary of Significance Levels				  */
/******************************************************************************/

/* Data */
cd "`directory'\Data"
use Differences, clear

/* Directory */
global directory = "[redacted-path-1cfebb260d42]"
cd "$directory\Data"
